inline double muffin_weight(float tau1decayMode, float ptratio, float tau1Pt, float nsmalljets, float nbtags, float tau1Eta) {
    const float x[6] = {tau1decayMode, ptratio, tau1Pt, nsmalljets, nbtags, tau1Eta};
  return MUFFIN_POSTER_NOPHI::eval(x, MUFFIN_POSTER_NOPHI::FEAT_nominal, MUFFIN_POSTER_NOPHI::THR_nominal, MUFFIN_POSTER_NOPHI::LEFT_nominal,
                  MUFFIN_POSTER_NOPHI::RIGHT_nominal, MUFFIN_POSTER_NOPHI::MISS_nominal, MUFFIN_POSTER_NOPHI::OFF_nominal,
                  MUFFIN_POSTER_NOPHI::NTREE_nominal, MUFFIN_POSTER_NOPHI::B0_nominal, MUFFIN_POSTER_NOPHI::NORM_nominal);
}

